import {useRef,useState} from 'react';
import type {OpenRun,TableCell} from '../lib/open-engine';
type Row=Record<string,TableCell>;
function Plot({rows,xKey,yKey,label,xLabel,yLabel,band=false,points=false,step=false}:{rows:Row[];xKey:string;yKey:string;label:string;xLabel:string;yLabel:string;band?:boolean;points?:boolean;step?:boolean}){
 const ref=useRef<SVGSVGElement>(null);const data=rows.filter(r=>typeof r[xKey]==='number'&&typeof r[yKey]==='number'&&Number.isFinite(r[xKey])&&Number.isFinite(r[yKey])).slice(0,1000);if(!data.length)return null;
 const xs=data.map(r=>Number(r[xKey])),ys=data.flatMap(r=>[Number(r[yKey]),...(band&&typeof r.low==='number'&&typeof r.high==='number'?[r.low,r.high]:[])]);const a=Math.min(...xs),b=Math.max(...xs),c=Math.min(...ys),d=Math.max(...ys);const X=(v:number)=>65+535*(v-a)/(b-a||1),Y=(v:number)=>275-235*(v-c)/(d-c||1);const path=data.map((r,i)=>`${i?(step?'H':'L'):'M'}${X(Number(r[xKey]))}${i&&step?`V${Y(Number(r[yKey]))}`:` ${Y(Number(r[yKey]))}`}`).join(' ');
 function save(){const url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(ref.current!)],{type:'image/svg+xml'}));const link=document.createElement('a');link.href=url;link.download=label.replace(/[^a-z0-9]+/gi,'-')+'.svg';link.click();URL.revokeObjectURL(url);}
 return <figure className="open-chart"><figcaption>{label} <button className="btn small" onClick={save}>Save SVG</button></figcaption><svg ref={ref} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 340" role="img" aria-label={label} style={{background:'#fff',color:'#243b35'}}><path d="M65 35V275H605" fill="none" stroke="#6d7d76"/>{[0,.25,.5,.75,1].map(t=><g key={t}><text x={65+535*t} y="297" textAnchor="middle" fill="#243b35" fontSize="10">{(a+(b-a)*t).toPrecision(3)}</text><text x="57" y={279-235*t} textAnchor="end" fill="#243b35" fontSize="10">{(c+(d-c)*t).toPrecision(3)}</text></g>)}{band&&<path d={data.filter(r=>typeof r.low==='number'&&typeof r.high==='number').map((r,i)=>`${i?'L':'M'}${X(Number(r[xKey]))} ${Y(Number(r.low))}`).join(' ')+data.filter(r=>typeof r.low==='number'&&typeof r.high==='number').slice().reverse().map(r=>`L${X(Number(r[xKey]))} ${Y(Number(r.high))}`).join(' ')+'Z'} fill="#9270f4" opacity=".15"/>}{points?data.map((r,i)=><circle key={i} cx={X(Number(r[xKey]))} cy={Y(Number(r[yKey]))} r="2.5" fill="#197467" opacity=".6"/>):<path d={path} fill="none" stroke="#197467" strokeWidth="2.5"/>}<text x="330" y="327" textAnchor="middle" fill="#243b35" fontSize="12">{xLabel}</text><text x="13" y="155" transform="rotate(-90 13 155)" textAnchor="middle" fill="#243b35" fontSize="12">{yLabel}</text></svg><small>Rendered from actual engine output. Exact values are in the tables and reproduction bundle.{rows.length>1000?' Plot limited to the first 1,000 rows.':''}</small></figure>;
}
export default function MethodVisuals({run}:{run:OpenRun}){
 const t=run.result.tables;const [variable,setVariable]=useState('');const vars=[...new Set((t.chainMeans||[]).map(r=>String(r.variable)))];const term=variable||vars[0];
 return <div>
 {t.curve&&<Plot rows={t.curve} xKey="x" yKey="estimate" label="Nonlinear fitted mean and pointwise 95% interval" xLabel="Smooth predictor" yLabel="Expected outcome" band/>}
 {t.survival&&<Plot rows={[{time:0,survival:1,low:1,high:1},...t.survival]} xKey="time" yKey="survival" label="Observed Kaplan–Meier survival" xLabel="Follow-up time" yLabel="Survival probability" step/>}
 {t.trajectory&&<Plot rows={t.trajectory} xKey="time" yKey="mean" label="Observed wave means — not individual trajectories" xLabel="Observation time" yLabel="Observed mean"/>}
 {t.residuals&&<Plot rows={t.residuals} xKey="fitted" yKey="residual" label="Residuals versus fitted values" xLabel="Fitted value" yLabel="Residual" points/>}
 {t.studies&&<Plot rows={t.studies} xKey="estimate" yKey="se" label="Effect-size / standard-error scatter (descriptive)" xLabel="Effect estimate" yLabel="Standard error" points/>}
 {t.quantiles&&[...new Set(t.quantiles.map(r=>String(r.term)))].map(term=><Plot key={term} rows={t.quantiles.filter(r=>r.term===term)} xKey="tau" yKey="estimate" label={`Quantile coefficient profile: ${term}`} xLabel="Conditional quantile" yLabel="Coefficient (no profile intervals)"/>)}
 {t.chainMeans&&<><label className="lab-field">Imputation trace variable<select value={term} onChange={e=>setVariable(e.target.value)}>{vars.map(v=><option key={v}>{v}</option>)}</select></label>{[...new Set(t.chainMeans.filter(r=>r.variable===term).map(r=>String(r.chain)))].slice(0,5).map(chain=><Plot key={chain} rows={t.chainMeans.filter(r=>r.variable===term&&String(r.chain)===chain).map(r=>({...r,iteration:Number(r.iteration)}))} xKey="iteration" yKey="mean" label={`Imputation trace: ${term}, chain ${chain}`} xLabel="Iteration" yLabel="Imputed mean"/>)}<small>First five chains displayed. All traces are retained; visual stability alone does not establish convergence.</small></>}
 </div>;
}
